import re

JETON = re.compile(r'\s*(?:(?P<sayi>-?\d+(?:\.\d+)?)|(?P<metin>"[^"]*")|(?P<op>[<>]=?|==|!=)|(?P<ad>[A-Za-z_]+))')

def jetonla(s):
    out, i = [], 0
    while i < len(s):
        m = JETON.match(s, i)
        if not m:
            raise ValueError("cozumlenemeyen: " + s[i:])
        i = m.end()
        tur = m.lastgroup
        out.append((tur, m.group(tur)))
    return out

KARSILASTIR = {
    ">": lambda a, b: a > b, "<": lambda a, b: a < b,
    ">=": lambda a, b: a >= b, "<=": lambda a, b: a <= b,
    "==": lambda a, b: a == b, "!=": lambda a, b: a != b,
}

def derle(kural):
    jetonlar = jetonla(kural)
    kosullar, i = [], 0
    while i < len(jetonlar):
        tur, alan = jetonlar[i]
        assert tur == "ad", "alan adi bekleniyordu"
        _, op = jetonlar[i + 1]
        tur2, ham = jetonlar[i + 2]
        deger = float(ham) if tur2 == "sayi" else ham.strip('"')
        kosullar.append((alan, KARSILASTIR[op], deger))
        i += 3
        if i < len(jetonlar):
            assert jetonlar[i] == ("ad", "ve"), "yalnizca 've' destekleniyor"
            i += 1
    def calistir(olay):
        return all(f(olay[a], d) for a, f, d in kosullar)
    return calistir

