from itertools import product

SURUMLER = {"log": ["1.2.0", "1.5.0", "1.7.3", "1.9.0", "2.0.0"]}

def ayristir(v):
    return tuple(int(x) for x in v.split("."))

def caret(v):
    alt = ayristir(v)
    return lambda s: alt <= ayristir(s) < (alt[0] + 1, 0, 0)

def aralik(a, b):
    return lambda s: ayristir(a) <= ayristir(s) < ayristir(b)

kisitlar = {"A": caret("1.2.0"), "B": aralik("1.5.0", "1.8.0")}
